-- =============================================================================
-- 01-admin/08-fu-public-group-migration.sql
-- =============================================================================
-- =====================================================
-- FU Public Group Migration (idempotent / upgrade-safe)
-- =====================================================
-- 「进入工作区选团队 + 每个团队只看本团队与 Public」模型的数据侧：
--   1) 创建内置 Public 开发组（vg-dev-public）——其功能单元对所有能进入工作区者始终可见（叠加层）。
--      用户不会成为该组成员，故它不出现在「我的团队」选择列表中，仅由后端代码叠加可见。
--   2) 历史功能单元归入 Public：
--        (a) 完全无团队分配的 FU
--        (b) 分配给过渡期「Default Development Team」(vg-default-dev-team) 的 FU
--      → 保证切换到新模型后这些历史 FU 对所有用户仍可见。
--   3) 清理已被 Public 取代的 vg-default-dev-team 分配（该组当初仅为可见性兜底）。
-- 说明：显式分配给「真实团队」（非 default）的 FU 保持团队隔离，不被公开。
-- 幂等：仅影响「无分配 / default 团队」的 FU，可安全重复执行；不会误将新建的团队 FU 公开。
-- =====================================================


-- 1) 内置 Public 开发组（CUSTOM，无成员，作为始终可见的叠加层）
INSERT INTO sys_virtual_groups (id, code, name, type, display_name, status, created_at, updated_at)
VALUES ('vg-dev-public', 'DEV_TEAM_PUBLIC', 'Public', 'CUSTOM',
        'Built-in public group: its function units are visible to every developer-workstation user', 'ACTIVE',
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON CONFLICT (code) DO NOTHING;

-- 2) 历史 FU → Public（无分配的 + 过渡期默认团队的）
INSERT INTO dw_function_unit_dev_groups (function_unit_id, virtual_group_id, created_at, created_by)
SELECT DISTINCT fu.id, 'vg-dev-public', CURRENT_TIMESTAMP, 'system'
FROM dw_function_units fu
WHERE NOT EXISTS (
        SELECT 1 FROM dw_function_unit_dev_groups g WHERE g.function_unit_id = fu.id
      )
   OR EXISTS (
        SELECT 1 FROM dw_function_unit_dev_groups g2
        WHERE g2.function_unit_id = fu.id AND g2.virtual_group_id = 'vg-default-dev-team'
      )
ON CONFLICT (function_unit_id, virtual_group_id) DO NOTHING;

-- 3) 清理被 Public 取代的过渡期默认团队分配
DELETE FROM dw_function_unit_dev_groups WHERE virtual_group_id = 'vg-default-dev-team';

-- =============================================================================
-- 01-admin/09-remove-fu-viewer-role.sql
-- =============================================================================
-- =====================================================
-- Remove deprecated FU_VIEWER (Function Unit Viewer) role
-- =====================================================
-- Fresh installs still run 01-create-roles-and-groups.sql / 02-init-developer-permissions.sql
-- which insert FU_VIEWER; this script removes that role and related bindings afterwards.
-- Team read access no longer depends on FU_VIEWER (membership / other DW roles suffice).
-- Idempotent: safe to re-run.
-- =====================================================

-- Explicit cleanup (role FK children mostly CASCADE; clear known bindings first for clarity)
DELETE FROM sys_virtual_group_roles WHERE role_id = 'role-fu-viewer';
DELETE FROM sys_developer_role_permissions WHERE role_id = 'role-fu-viewer';
DELETE FROM sys_role_assignments WHERE role_id = 'role-fu-viewer';
DELETE FROM sys_user_roles WHERE role_id = 'role-fu-viewer';
DELETE FROM sys_user_business_unit_roles WHERE role_id = 'role-fu-viewer';
DELETE FROM sys_business_unit_roles WHERE role_id = 'role-fu-viewer';
DELETE FROM sys_roles WHERE id = 'role-fu-viewer' OR code = 'FU_VIEWER';

-- =============================================================================
-- 01-admin/10-add-auditor-role-type.sql
-- =============================================================================
-- Promote the built-in AUDITOR role off ADMIN type and clamp its DW permissions
-- to FUNCTION_UNIT_VIEW only. Targets role code AUDITOR; do not apply to all ADMIN roles.


UPDATE sys_roles
SET type = 'AUDITOR',
    updated_at = CURRENT_TIMESTAMP
WHERE code = 'AUDITOR'
  AND type IS DISTINCT FROM 'AUDITOR';

DELETE FROM sys_developer_role_permissions
WHERE role_id IN (SELECT id FROM sys_roles WHERE code = 'AUDITOR')
  AND permission <> 'FUNCTION_UNIT_VIEW';

INSERT INTO sys_developer_role_permissions (id, role_id, permission, created_at)
SELECT
    gen_random_uuid()::varchar,
    r.id,
    'FUNCTION_UNIT_VIEW',
    CURRENT_TIMESTAMP
FROM sys_roles r
WHERE r.code = 'AUDITOR'
ON CONFLICT (role_id, permission) DO NOTHING;

