-- =============================================================================
-- 90-post-seed/00-align-id-sequences.sql
-- =============================================================================
-- =============================================================================
-- Align all dw_* / rt_* BIGSERIAL `id` sequences with MAX(id).
--
-- Why this lives under 90-post-seed/ (its own stage, not 00-schema/, not 99-maintenance/):
--   This is the "finalize / post-seed" stage of `00-init-all.sh`:
--     * NOT schema DDL  -> would not belong under 00-schema/.
--     * NOT on-demand maintenance -> would not belong under 99-maintenance/.
--     * NOT tied to one Function Unit -> would not belong under 08-/15-/16-/17-.
--   It is "every init must run AFTER all seed scripts are loaded", an
--   independent stage that any future post-seed alignment can join.
--
-- Why this script is necessary:
--   `17-Multi-Instance-Subtask-Demo/00-init-kk.sql` is exported from a real
--   dev environment and uses `INSERT INTO ... (id, ...) VALUES (<explicit>, ...)`
--   across ~12 tables (dw_function_units, dw_table_definitions,
--   dw_field_definitions, dw_action_definitions, dw_form_definitions,
--   dw_form_table_bindings, dw_sub_table_view_configs, dw_sub_table_view_fields,
--   dw_table_relations, dw_process_definitions, rt_table_definitions,
--   rt_field_definitions, rt_table_versions). PostgreSQL `BIGSERIAL` does NOT
--   advance its sequence when an INSERT supplies an explicit value, so on first
--   container start `last_value` stays at 1 while `MAX(id)` is much higher.
--   The very first JPA `GenerationType.IDENTITY` insert through the app then
--   collides on the primary key:
--     ERROR: duplicate key value violates unique constraint "<table>_pkey"
--   (first reproduced on `dw_form_table_bindings_pkey` when the Designer's
--   Manage Table Bindings dialog tried to "Add" a sub-table binding).
--
-- Execution timing:
--   `00-init-all.sh` invokes this script explicitly in its post-seed stage,
--   right after the last seed package (18-MCY).
--   Putting it any earlier would see empty tables and become a no-op.
--
-- Defensive coverage:
--   Dynamically discovers every `public.dw_*` and `public.rt_*` table that has
--   a serial sequence on `id`. So any future seed package using the same
--   explicit-id pattern is automatically protected -- no per-table list to
--   maintain. Idempotent; safe to re-run on every fresh init.
-- =============================================================================

DO $align_id_sequences$
DECLARE
  v_tbl  TEXT;
  v_seq  TEXT;
  v_next BIGINT;
BEGIN
  -- Only tables that have an `id` column: pg_get_serial_sequence raises (rather
  -- than returning NULL) when the column is missing, e.g. dw_ai_studio_proposal_jobs
  -- keys on job_id.
  FOR v_tbl IN
    SELECT table_name
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND column_name = 'id'
      AND (table_name LIKE 'dw\_%' ESCAPE '\'
        OR table_name LIKE 'rt\_%' ESCAPE '\')
    ORDER BY table_name
  LOOP
    v_seq := pg_get_serial_sequence(quote_ident(v_tbl), 'id');
    IF v_seq IS NULL THEN
      CONTINUE;
    END IF;

    EXECUTE format(
      'SELECT GREATEST(COALESCE((SELECT MAX(id) FROM %I), 0), 1)',
      v_tbl
    ) INTO v_next;

    PERFORM setval(v_seq::regclass, v_next);
  END LOOP;
END $align_id_sequences$;

-- =============================================================================
-- 90-post-seed/01-assign-seed-function-units-to-public.sql
-- =============================================================================
-- =====================================================
-- Post-seed: 种子功能单元归入 Public 开发组（幂等）
-- =====================================================
-- 背景：`01-admin/08-fu-public-group-migration.sql` 负责创建内置 Public 组
-- （vg-dev-public）并把「无团队归属」的历史 FU 归入该组。但它在 [3/6] 阶段执行，
-- 早于 08-/15-/16-/17-/18-/19- 各 FU 种子包（[4/6]、[5x/6]），因此在全新库上
-- 它的 FU 回填部分恒为 no-op —— 种子 FU 全部落地为「无归属」孤儿。
--
-- 后果：`FunctionUnitWorkspaceAccessService.visibleFunctionUnitIds()` 完全按组
-- 归属计算可见性，没有「未分配 = 全员可见」兜底。孤儿 FU 只在「管理员且未选团队」
-- 时可见；一旦选了任何团队，Developer Workstation 的功能单元列表就是空的。
--
-- 本脚本在所有种子包之后补齐该归属，使新装环境行为与 08 迁移的既定语义一致。
--
-- 幂等：仅插入「当前无任何组归属」的 FU；已显式分配到真实团队的 FU（如
-- Platform Showcase → vg-tech-leads，用于工作区权限演示）保持团队隔离，不被公开。
-- =====================================================


-- 兜底：Public 组必须存在（正常情况下 01-admin/08 已建；此处防止单独执行本脚本时外键悬空）
INSERT INTO sys_virtual_groups (id, code, name, type, display_name, status, created_at, updated_at)
VALUES ('vg-dev-public', 'DEV_TEAM_PUBLIC', 'Public', 'CUSTOM',
        'Built-in public group: its function units are visible to every developer-workstation user', 'ACTIVE',
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON CONFLICT (code) DO NOTHING;

-- 无任何组归属的 FU → Public
INSERT INTO dw_function_unit_dev_groups (function_unit_id, virtual_group_id, created_at, created_by)
SELECT fu.id, 'vg-dev-public', CURRENT_TIMESTAMP, 'system'
FROM dw_function_units fu
WHERE NOT EXISTS (
        SELECT 1 FROM dw_function_unit_dev_groups g WHERE g.function_unit_id = fu.id
      )
ON CONFLICT (function_unit_id, virtual_group_id) DO NOTHING;

DO $$
DECLARE
    v_public  INTEGER;
    v_orphan  INTEGER;
BEGIN
    SELECT COUNT(*) INTO v_public
    FROM dw_function_unit_dev_groups WHERE virtual_group_id = 'vg-dev-public';

    SELECT COUNT(*) INTO v_orphan
    FROM dw_function_units fu
    WHERE NOT EXISTS (
        SELECT 1 FROM dw_function_unit_dev_groups g WHERE g.function_unit_id = fu.id
    );

    RAISE NOTICE '  Function units in Public group: %', v_public;
    RAISE NOTICE '  Function units still unassigned: %', v_orphan;

    IF v_orphan > 0 THEN
        RAISE WARNING '  % function unit(s) have no dev-group assignment and will be invisible in the workspace', v_orphan;
    END IF;
END $$;

